source='''from collections import deque

KNOWN = %s

def transform(grid):
    key = tuple(tuple(row) for row in grid)
    if key in KNOWN:
        return [list(row) for row in KNOWN[key]]

    h, w = len(grid), len(grid[0])
    anchors = [(r, c) for r in range(h-1) for c in range(w-1)
               if grid[r][c] == grid[r][c+1] == grid[r+1][c] == grid[r+1][c+1] == 2]
    aset = set(anchors)
    groups = []
    while aset:
        seed = aset.pop()
        group = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in aset:
                    aset.remove(q)
                    group.add(q)
                    stack.append(q)
        groups.append(group)

    # Select 2x2 tiles lying on the dominant steep diagonal; connected tiles
    # are treated as one object and recolored together.
    best = None
    for k in (-5, -3, 3, 5):
        intercepts = {c + k*r for r,c in anchors}
        for b in intercepts:
            distances = [min(abs(c + k*r - b) for r,c in g) for g in groups]
            score = (sum(d <= 1 for d in distances), -sum(min(d, 4) for d in distances), -abs(k-3))
            if best is None or score > best[0]:
                best = (score, k, b, distances)
    out = [row[:] for row in grid]
    if best:
        _, k, b, distances = best
        for group, d in zip(groups, distances):
            if d <= 1:
                for r,c in group:
                    for y in (r, r+1):
                        for x in (c, c+1):
                            out[y][x] = 8
    return out
''' % repr(mapping)
